// Voor elke flow: bereken open_rate, click_rate, revenue_7d, unsubscribe_rate.
// Vergelijk met vorige 7 dagen. Flag als:
//   - open_rate < 20%
//   - daling > 30% vs vorige week op open OF click OF revenue
// Health: Good / Needs Attention / Critical

const flows = items[0].json.data || [];
const flagged = [];
const results = [];

for (const flow of flows) {
  const openRate = flow.open_rate || 0;
  const clickRate = flow.click_rate || 0;
  const revenue = flow.revenue_7d || 0;
  const prevOpenRate = flow.prev_open_rate || openRate;
  const prevRevenue = flow.prev_revenue_7d || revenue;
  const unsubRate = flow.unsubscribe_rate || 0;

  const openDelta = prevOpenRate > 0 ? ((openRate - prevOpenRate) / prevOpenRate) * 100 : 0;
  const revDelta = prevRevenue > 0 ? ((revenue - prevRevenue) / prevRevenue) * 100 : 0;

  let health = 'Good';
  let reason = '';

  if (openRate < 0.20 || unsubRate > 0.01 || openDelta < -30 || revDelta < -30) {
    health = 'Critical';
    reason = openRate < 0.20 ? `Open rate ${(openRate*100).toFixed(1)}% onder 20%` : (openDelta < -30 ? `Open rate -${Math.abs(openDelta).toFixed(0)}% vs vorige week` : `Revenue -${Math.abs(revDelta).toFixed(0)}% vs vorige week`);
    flagged.push({ ...flow, health, reason });
  } else if (openRate < 0.25 || clickRate < 0.02 || openDelta < -15) {
    health = 'Needs Attention';
    reason = `Open ${(openRate*100).toFixed(1)}% / Click ${(clickRate*100).toFixed(1)}%`;
  }

  results.push({
    json: {
      flow_name: flow.name,
      flow_id: flow.id,
      type: flow.trigger_type || 'Unknown',
      status: flow.status,
      sends: flow.sends || 0,
      open_rate: openRate,
      click_rate: clickRate,
      revenue_attributed: revenue,
      unsubscribe_rate: unsubRate,
      last_updated: new Date().toISOString(),
      health,
      reason
    }
  });
}

return [{ json: { results, flagged, flaggedCount: flagged.length, totalFlows: results.length } }];

